'use client';

import { useState } from 'react';
import type { CaseEvent, CaseView } from '../../contracts';
import { Conversation } from './conversation';
import { CaseDetails } from './case-details';
import { createDraftIntent, createMessageIntent } from './intents';
import styles from './workspace.module.css';

export interface CaseWorkspaceProps {
  view: CaseView | null;
  onIntent: (intent: CaseEvent) => void;
  loading?: boolean;
  fieldLabels?: Record<string, string>;
}

export function CaseWorkspace({ view, onIntent, loading = false, fieldLabels }: CaseWorkspaceProps) {
  if (loading) return <p role="status">Cargando expediente…</p>;
  if (!view) return <p role="status">No hay ningún expediente disponible.</p>;
  return <WorkspaceContent key={`${view.snapshot.caseId}:${view.draft?.draftId ?? ''}:${view.draft?.text ?? ''}`} view={view} onIntent={onIntent} fieldLabels={fieldLabels} />;
}

function WorkspaceContent({ view, onIntent, fieldLabels }: { view: CaseView; onIntent: (intent: CaseEvent) => void; fieldLabels?: Record<string, string> }) {
  const [draftText, setDraftText] = useState(view.draft?.text ?? '');
  const [message, setMessage] = useState('');
  const actionLabels: Record<string, string> = { CLARIFY: 'Aclarar información', ANSWER_QUESTION: 'Responder pregunta', PROPOSE_CALL: 'Proponer llamada', HANDOFF: 'Derivar a una persona', WAIT: 'Esperar', STOP_CONTACT: 'No contactar' };
  const stale = view.activeProposal?.status === 'superseded';
  const canReview = !!view.draft && !!view.activeProposal && !stale && view.draft.proposalId === view.activeProposal.proposalId && !['approved', 'discarded'].includes(view.draft.status);
  const submitDraft = (type: 'DRAFT_EDITED' | 'DRAFT_APPROVED' | 'DRAFT_DISCARDED') => {
    const intent = createDraftIntent(view, type, draftText);
    if (intent) onIntent(intent);
  };
  return <div className={styles.workspace}>
    <p className={styles.muted}>Modo de generación: {view.aiMode === 'replay' ? 'replay simulado' : 'OpenAI'}</p>
    {(view.errors.length > 0 || view.warnings.length > 0) && <section className={styles.error} role="alert">{view.errors.map((error, i) => <p key={`${error.code}-${i}`}>{error.message}{error.retryable ? ' · Puede volver a intentarlo.' : ''}</p>)}{view.warnings.map((warning, i) => <p key={i}>{warning}</p>)}</section>}
    <div className={styles.columns}><div><Conversation messages={view.snapshot.messages} />
      <section className={`${styles.panel} ${styles.entry}`}><h3>Añadir mensaje ficticio</h3><p className={styles.muted}>Prepara una entrada simulada para esta demo.</p>{view.aiMode === 'replay' && <p className={styles.muted}>Replay reconoce solo los mensajes sintéticos preparados. Para Laura puedes probar: «Sí, los 3.800 € ya son después del coche.»</p>}<form onSubmit={event => { event.preventDefault(); const intent = createMessageIntent(view, message); if (intent) { onIntent(intent); setMessage(''); } }}><label htmlFor="customer-message">Mensaje del cliente</label><textarea id="customer-message" value={message} onChange={event => setMessage(event.target.value)} placeholder="Escribe una respuesta ficticia…" /><button type="submit" disabled={!message.trim()}>Añadir mensaje simulado</button></form></section>
    </div><div><CaseDetails snapshot={view.snapshot} fieldLabels={fieldLabels} />
      <section className={`${styles.panel} ${styles.recommendation}`} aria-labelledby="recommendation-title"><span className={styles.eyebrow}>SIGUIENTE PASO</span><h2 id="recommendation-title">Recomendación del copiloto</h2>
        {view.activeProposal ? <><div className={styles.action}>{actionLabels[view.activeProposal.actionType] ?? view.activeProposal.actionType}</div><p>{view.activeProposal.reason}</p><p className={styles.muted}>Evidencia: {view.activeProposal.evidenceRefs.map(ref => ref.messageId).join(', ') || 'sin referencias'}</p>{stale && <p className={styles.error}>Propuesta desactualizada. Reevalúa el caso antes de aprobar.</p>}</> : <p className={styles.muted}>No hay propuesta disponible.</p>}
        {view.draft && <><label htmlFor="draft">Borrador para revisión</label><textarea id="draft" value={draftText} onChange={event => setDraftText(event.target.value)} disabled={!canReview} /><p className={styles.muted}>{view.draft.status === 'approved' ? 'Pendiente de comunicación. La aprobación no implica envío ni acuerdo.' : view.draft.status === 'discarded' ? 'Borrador descartado.' : 'Editable por el asesor. No se enviará automáticamente.'}</p><div className={styles.buttons}><button type="button" disabled={!canReview || !draftText.trim()} onClick={() => submitDraft('DRAFT_EDITED')}>Guardar edición</button><button type="button" disabled={!canReview || draftText !== view.draft.text} onClick={() => submitDraft('DRAFT_APPROVED')}>Aprobar borrador</button><button type="button" disabled={!canReview} onClick={() => submitDraft('DRAFT_DISCARDED')}>Descartar</button></div>{canReview && draftText !== view.draft.text && <p className={styles.muted}>Guarda la edición antes de aprobar.</p>}</>}
      </section></div></div>
  </div>;
}
import type { FactView, CaseSnapshot } from '../../contracts';
import styles from './workspace.module.css';

const statusLabels: Record<FactView['status'], string> = { known: 'declarado', approximate: 'aproximado', unknown: 'desconocido', ambiguous: 'requiere aclaración', conflicting: 'contradictorio', not_applicable: 'no aplica' };
function valueText(fact: FactView): string {
  if (!('value' in fact) || fact.value === undefined) return statusLabels[fact.status];
  const value = fact.value;
  if (Array.isArray(value)) return value.join(', ');
  if (typeof value === 'object') return `${value.min.toLocaleString('es-ES')}–${value.max.toLocaleString('es-ES')}${fact.unit === 'EUR' ? ' €' : ''}`;
  return typeof value === 'number' ? `${value.toLocaleString('es-ES')}${fact.unit === 'EUR' ? ' €' : ''}` : String(value);
}
const milestoneStatus: Record<string, string> = { pending: 'pendiente', in_progress: 'en curso', blocked: 'bloqueado', completed: 'completado', not_applicable: 'no aplica', waived: 'dispensado' };
const caseStatus: Record<CaseSnapshot['status'], string> = { NEEDS_ADVISOR: 'Requiere asesor', READY_TO_REPLY: 'Respuesta preparada', WAITING_CUSTOMER: 'Esperando respuesta', ON_HOLD_REVIEW: 'Revisión humana', NEXT_STEP_AGREED: 'Siguiente paso acordado', CLOSED: 'Cerrado', DO_NOT_CONTACT: 'No contactar' };
const scopeLabels = { case: 'caso', participant: 'persona', buying_unit: 'unidad de compra' };
export function CaseDetails({ snapshot, fieldLabels = {} }: { snapshot: CaseSnapshot; fieldLabels?: Record<string, string> }) {
  return <section aria-labelledby="details-title" className={styles.panel}>
    <div className={styles.panelHeader}><div><span className={styles.eyebrow}>EXPEDIENTE</span><h2 id="details-title">Contexto del caso</h2></div><span className={styles.badge}>Revisión {snapshot.revision}</span></div>
    <p className={styles.muted}>{snapshot.goal.description} · {caseStatus[snapshot.status]}</p>
    <h3>Progreso comercial</h3><div className={styles.milestones}>{snapshot.workflowProgress.milestones.map(m => <div key={m.milestoneId} className={styles.milestone}><b>{m.milestoneId}</b><span>{milestoneStatus[m.status] ?? m.status}</span></div>)}</div>
    <h3>Datos declarados</h3><dl className={styles.facts}>{snapshot.knowledge.facts.map((fact, index) => <div key={`${fact.fieldId}-${fact.subjectRef.id}-${index}`}><dt>{fieldLabels[fact.fieldId] ?? fact.fieldId.replaceAll('_', ' ')}</dt><dd><strong>{valueText(fact)}</strong><small>{statusLabels[fact.status]} · {scopeLabels[fact.subjectRef.scope]}{fact.incomeBasis ? ` · ${fact.incomeBasis === 'net' ? 'neto' : fact.incomeBasis === 'gross' ? 'bruto' : 'neto/bruto desconocido'}` : ''}{fact.period ? ` · ${fact.period === 'month' ? 'mensual' : fact.period}` : ''}{fact.evidenceRefs.length > 0 ? ` · ${fact.evidenceRefs.map(e => e.messageId).join(', ')}` : ''}</small></dd></div>)}</dl>
    <h3>Dudas y alertas</h3>{snapshot.blockers.length ? snapshot.blockers.map(blocker => <div className={styles.alert} key={blocker.id}><strong>{blocker.description}</strong><small>{blocker.evidenceRefs.map(ref => ref.messageId).join(', ')}</small></div>) : <p className={styles.muted}>No hay alertas registradas.</p>}
  </section>;
}
"}}}

