 23	function matches(rule: PolicyRule, input: PolicyInput): { matches: boolean; evidenceRefs: EvidenceRef[] } {
 24	  if (rule.requiredOption && !input.policy.advisoryCall[rule.requiredOption]) return { matches: false, evidenceRefs: [] };
 25	  if (rule.id === 'R08' && !agreementIsCurrent(input.events)) return { matches: false, evidenceRefs: [] };
 26	  if (rule.id === 'R09' && !approvalPending(input.events)) return { matches: false, evidenceRefs: [] };
 27	  const blockers = input.blockers.filter(b => b.status === 'open' && rule.blockerTypesAny?.includes(b.type));
 28	  if (rule.blockerTypesAny && !blockers.length) return { matches: false, evidenceRefs: [] };
 29	  const events = input.events.filter(e => rule.eventTypesAny?.includes(e.type));
 30	  if (rule.eventTypesAny && !events.length) return { matches: false, evidenceRefs: [] };
 31	  const guard = rule.condition ? evaluateCondition(rule.condition, { ...input, policyOptions: input.policy.advisoryCall }) : undefined;
 32	  if (guard && !(rule.conditionResults ?? ['satisfied']).includes(guard.result)) return { matches: false, evidenceRefs: [] };
 33	  return { matches: true, evidenceRefs: uniqueEvidence([...blockers.flatMap(b => b.evidenceRefs), ...events.flatMap(e => 'evidenceRefs' in e.payload ? e.payload.evidenceRefs : []), ...(guard?.evidenceRefs ?? [])]) };
