 36	/** Protected guards cannot be relaxed by editable commercial rules or profile preferences. */
 37	export function evaluatePolicy(input: PolicyInput): PolicyDecision {
 38	  const actions = input.actionCatalog.actions.map(a => a.id);
 39	  const protectedDecision = (result: PolicyDecision['result'], action: string, ruleId: string, reason: string, evidenceRefs: EvidenceRef[]): PolicyDecision => ({ result, allowedActions: actions.includes(action) ? [action] : [], prohibitedActions: actions.filter(a => a !== action), ruleIds: [ruleId], priority: Number.MAX_SAFE_INTEGER, reviewRequired: true, reasons: [reason], evidenceRefs: uniqueEvidence(evidenceRefs) });
 40	  const optOut = input.events.filter(e => e.type === 'DO_NOT_CONTACT_REQUESTED');
 41	  const optOutBlockers = input.blockers.filter(b => b.status === 'open' && b.type === 'OPT_OUT');
 42	  if (optOut.length || optOutBlockers.length) return protectedDecision('STOP_CONTACT', 'STOP_CONTACT', 'R01', 'El cliente solicita no ser contactado', [...optOut.flatMap(e => e.payload.evidenceRefs), ...optOutBlockers.flatMap(b => b.evidenceRefs)]);
 43	  const critical = input.blockers.filter(b => b.status === 'open' && ['BINDING_CLAIM', 'URGENT'].includes(b.type));
 44	  if (critical.length) return protectedDecision('HUMAN_REVIEW_REQUIRED', 'HANDOFF', 'R02', 'La solicitud requiere revisión humana', critical.flatMap(b => b.evidenceRefs));
 45	  const objections = input.blockers.filter(b => b.status === 'open' && ['TRUST', 'PRODUCT', 'COST', 'PRIVACY', 'TIME', 'FIT'].includes(b.type));
 46	  if (objections.length) return protectedDecision('HUMAN_REVIEW_REQUIRED', 'HANDOFF', 'R07', 'La cuestión requiere una fuente autorizada o revisión humana', objections.flatMap(b => b.evidenceRefs));
